import{_ as t,c as s,o as n,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"孔易阐真*杂卦传","description":"周易阐真 - 孔易阐真*杂卦传","frontmatter":{"title":"孔易阐真*杂卦传","description":"周易阐真 - 孔易阐真*杂卦传"},"headers":[],"relativePath":"zh/classics/chanzhen/066.md","filePath":"zh/classics/chanzhen/066.md"}'),c={name:"zh/classics/chanzhen/066.md"};function o(i,a,l,d,h,p){return n(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"孔易阐真-杂卦传",tabindex:"-1"},[r("孔易阐真*杂卦传 "),e("a",{class:"header-anchor",href:"#孔易阐真-杂卦传","aria-label":"Permalink to “孔易阐真*杂卦传”"},"​")],-1),e("p",null,"孔易阐真*杂卦传 ​乾刚，坤柔。 ​乾者，健也。健而又健，刚之至矣。取象为天，物之至刚者莫如天。天之为道，一气上下，流行不息，亘古如斯。惟其体刚，故能始万物而易知。人资天之气而始，即具此刚而易知之德。刚者，正气也，而命寓焉。修道者，造命之学，即养此刚健之正气耳。养正气必如天之易知，不为物屈，而后正气常存，命宝坚固，与天为徒矣。坤者，顺也。顺而又顺，柔之至矣。取象为地，物之至柔者莫如地。地之为道，至厚至静，至卑至下，永久不变。惟其体柔，故能生万物而简能。人资地之气而生，即具此柔而简能之德。柔者，真心也，而性寄焉。修道者，修性之学，即修此柔顺之真心耳。修真心必如地之简能，无物不载，而后心地虚静，真性不昧，与地为配矣。盖在天为易知者，在人为良知；在地为简能者，在人为良能。能刚则良知而易，不思而得；能柔则良能而简，不勉而中。良知良能，刚柔相合，健顺之德全，性命之事了。故古人谓金丹之道，至简至易之道也。比乐，师忧。 ​比者，亲比，以阴比阳也。五阴而比一阳，阴不陷阳而顺阳，顺以御险，致乐之道也。人之不能有乐者，以其陷真而顺假也。若能顺真以化假，则假亦归真，何不乐乎?师者，兵道，以正制邪也。一阳而帅五阴，阳不为阴所陷而统阴，险中行顺，备忧之道也。人之所以有忧者，以其能处顺，而不能处逆也。若能以顺而处逆，则逆亦是顺，有何忧乎?比以阴而顺阳，顺阳即不陷阳；师处逆而行顺，行顺而阳不陷。陷与不陷，是在顺与不顺耳。一顺而致乐备忧，无往不利矣。临、观之义，或与或求。 ​临者，亲近也。顺中有悦，悦在于顺，将欲取之，必先与之，不与而与，或与之也。观者，觉察也。顺时渐行，渐以行顺，顺其所欲，渐次导之，不求而求，或求之也。与必顺其悦，求必顺而巽，与之求之，总是一顺，所争者内顺外顺耳。外顺可以临物，取彼之欢心，借假而修真。内顺可以观己，增我之道德，由真而化假。以临而与，以观而求，彼悦而我即悦，先与后求，此顺道之所以为贵欤！屯见而不失其居，蒙杂而著。 ​屯者，迍邅难前也。一阳动于险中，道心发现之时。道心发现，内有主宰，不行险而防险，虽动而不失其居。特以一阳动于坎地，阳气初复，阴气正盛，未可妄动，不失其居，正欲待时以出险耳。蒙者，昏昧不明也。一阳陷于阴中，人心已生之时。人心已生，是非相混，不顺阳而陷阳，故杂而昏昧著外。然虽阳气陷于坎中，阳气未泯，阴气方著，正可随时止险耳。阳动险中，待时而进阳；阴陷其阳，随时而退阴。进阳退阴，各有其时，动之止之，不失其时，可以动而出险，止而济险，阳气不为阴气所伤矣。震，起也；艮，止也。 ​震者，一阳进于二阴之下，阳气顺时而起也，取象为雷。雷声之起，奋发而莫可遏止。雷外有雷，以此雷而及彼雷，千雷万雷，总在一起。修道者振发志气，一往直前，由近达远，亦必如雷之动，方为刚于起，而不为人欲所牵矣。艮者，一阳居于二阴之上，阳气顺时而止也，取象为山。山体之止，静定而永不迁移。山外有山，以此山而连彼山，千山万山，总是一止。修道者敛藏神气，不动不摇，由内达外，亦必如山之止，方是刚于止，而不为境遇所移矣。用刚，则震起而果决动直；养刚，则艮止而稳定静专。起之止之，能随其时，无往不可用刚，无处能伤其刚矣。损、益，盛衰之始也。 ​损者，减少也。悦于止而止其悦，止其不正之悦，而止于其所，损其柔之有余也。益者，增多也。动之巽而巽其动，进其不能之动而渐于能动，益其刚之不足也。损其柔之有余，柔而不至于过盛；益其刚之不足，刚而不至于有衰。然损之益之者，欲其刚柔俱归中正也。若损益太过，有余者损而必至于太衰，不足者益而必至于过盛，是损益又为盛衰之始也。故修道者，用增减之功，必以刚柔中正为指归。刚柔中正，刚中有柔，柔中有刚，刚柔一气，阴阳和合，金丹凝结矣。大畜，时也；无妄，灾也。 ​大畜者，大有养也。刚于止而止其刚，刚不妄用，随时而用，可刚则刚，可止则止，止于至善而不迁，大畜而能合时者也。无妄者，勇于事也。动之刚而刚于动，动之太猛，任性之刚，不宜刚而刚，不宜动而动，动之固执而不通，无妄而自招灾者也。夫刚在内者，严以治己，外不足而内有余，愈畜愈大，浩气充塞，养之足而行之通，无妄于内，自无妄于外也；刚在外者，躁以应物，外有余而内不足，有动有妄，乖和失中，涉于假而伤其真，养之不大，必行之不通也。然则，能大畜者，方能无妄；欲无妄者，先须大畜。若畜之不大，而欲行之无妄，虽无妄而实有妄，斯其所取灾也。修道者可不善养浩气，配义与道，以期其至诚无妄乎?萃聚，而升不来也。 ​萃者，聚也。内顺而外悦，顺则人欲俱死，悦则躁性俱化，人欲无而真阴现，躁性化而真阳还，阴阳相合，正气凝聚，金丹有象矣。升者，上也。内巽而外顺，巽则渐进于道，顺则敬谨于行，渐进而不过于刚，敬谨而不过于柔，刚柔相济，客气不来，金丹可全矣。但欲正气凝聚，须要顺其悦，先取彼之欢心，彼不悦而他家真实不得，顺其所悦，正于杀机中盗生气耳。欲客气不来，须要巽而能顺，先克己之私心，己不克而我家旧染不去，巽而能顺，正在顺道中行逆道耳。盗生气能萃，行逆道能升。能萃能升，真者聚而假者不来。萃至于五行攒簇，行至于至善无恶，有无一致，性命俱了矣。谦轻，而豫怠也。 ​谦者，虚其所有也。止于内而顺于外，绝不用刚也。然止刚而用柔，易于谦之太过，自轻而不知自重，有伤于刚，尤必贵乎顺中知止，止于其所，谦于外而不轻慢于内也。豫者，乐其所有也。顺于内而动于外，顺行其刚也。然阴顺而阳动，易于豫之太过，懈怠而不知防闲，有伤于柔，尤必贵乎动中用顺，顺守其正，豫于外而不懈怠于内也。不轻则为真谦，不怠则能长豫。不轻不怠，谦以致豫，豫而能谦，动之止之，无往不顺矣。噬嗑，食也；贲，无色也。 ​噬嗑者，口食物而必合也。动而必明，不使有一行违背乎理，如食物口合齿动，动必有时也。贲者，妆饰也。以明运止，不使有一时昏迷其性，如无色妆饰文采，质必以文也。动而不出于明，动而不妄；明而不出于止，明而有养。动必本明，动即明也；止出于明，止亦明也。动止皆明，自明明德，而止于至善，其明无处不在矣。兑见，而巽伏也。 ​见音现。兑者，一阴见于二阳之上，阳以阴济，刚而不至于过亢，其德和悦，取象为泽。泽之为物，上开下合，满而不溢，盈而不流，泽外有泽，泽泽相通，浸润甚多也。修道者，心平气和，内外如一，有若无，实若虚，不满不盈，必如泽泽相通，无物不浸，而后谓之和气外现矣。巽者，一阴伏于二阳之下，阳尊阴卑，柔而不至于太懦，其德善入，取象为风。风之为物，气刚行缓，不疾而渐达，不猛而深入，风后有风，风风相续，循序前进也。修道者，心坚志远，循序下功，以诚而入，以柔而用，不即不离，必如风风相续，无处不到，而后能以深造自得矣。柔而现外者，和刚也；柔而伏下者，进刚也。能和其刚，则刚藏于柔，刚而不至于有余；能进其刚，则柔求其刚，柔而不至于不及。此用柔而不伤其刚，见之伏之，无可无不可矣。随，无故也；蛊，则饬也。 ​随者，彼此相随也。阳动而阴悦，阳随阴而阴随阳，阴阳相随，有故者而即无故。人自先天失散，真性已昧，情欲乱起，已有故矣。今者以震求兑，于杀机中盗生机，情来归性，仍是无故之物，本来面目也。蛊者，事有败坏也。阴进而阳止，阴伤阳而阳止阴，阴为阳制，有蛊者饬即不蛊。人自后天用事，客气来入，主气有亏，是有蛊矣。今者以刚制柔，于后天中返先天，明善复初，仍是不蛊之物，天良本性也。无故用随，阳求阴也。有蛊则伤阴，顺阳也。阳求阴，借阴可以复阳；阴顺阳，借阳可以化阴。复阳化阴，随蛊之道尽矣。剥，烂也；复，反也。 ​剥者，消去也。五阴而剥消一阳，如人顺乎后天之阴。剥阳将尽，势必剥之不已，而坏烂肢体也。复者，回反也。一阳回反于五阴之下，如人逆回先天之阳，生机又见，渐可复阳于纯，而重现本面也。然剥者，即复之兆；反者，即不烂之几。能于方剥之时，顺而止之，不使剥阳于尽，借此剥余之微阳，别立乾坤，重安鼎炉，随其时而复之，则已失者可得，已去者能还，先天纯而后天化，更何有剥烂之患乎?晋，昼也；明夷，诛也。 ​晋者，明进也。由顺生明，明在暗出，如昼而出地之日，渐进而上，愈上愈明，光辉增升也。明夷者，明伤也。因顺败明，明入于暗，如夜而入地之日，渐退而下，愈下愈晦，光辉诛伤也。一自暗而出明，一自明而入暗，所争者顺内顺外耳。顺在内，则妄念不生而心诚，诚则能明矣；顺在外，则物欲所蔽而神昏，昏则失明矣。内顺者，逆道也；外顺者，顺道也。逆则生明，而明通；顺则诛明，而明晦。顺逆之间，明之得失系之。修道者，可不知其顺中用逆之道乎?井通，而困相遇也。 ​井者，养人之道，言其时通也。通所以达其道，然未巽化于人，先须巽化于己。己无险，而方可济人之险。盖养己不到，是险中之巽；养己已到，是巽以出险。出险而巽，养己毕而又养人，其所养不穷也。困者，艰难之境，言其相遇也。困所以验其德，但未能以济险，先贵能以处险，处险能悦，而济险遂悦。盖遇困不受，是悦行于险；遇困能受，是处险能悦。身可困而心不可困，虽遇困而亦亨矣。遇通养人，遇困养己。通时能养人者，困时必能养己；困时能养己者，通时即能养人。通困相遇，时有变而养亦有变。顺之逆之，俱皆有养，方谓修道之士也。咸，速也；恒，久也。 ​咸者，无心之感也。内止而外悦，悦本于止，止以求悦，止而能养，悦而能行，悦止相需，寂然不动，感而遂通，以神交而不以形交，阴阳隔碍潜通，言其速也。恒者，有心之恒也。内巽而外动，巽以运动，动必以巽，巽而不懦，动而不猛，巽动合一，心坚志远，不急不缓，自有为而入无为，功力由渐而顿，言其久也。夫所谓无心者，无人心也；有心者，有道心也。无人心而阴阳感之速，有道心而功力行之久。感速则出于自然，无修无为；恒久则出于勉强，有作有为。有为无为，各有妙诀，总在无人心、有道心分之。若到大道完成之后，有无俱不立，物我悉归空，入于至诚如神之地，不但人心用不着，即道心亦用不着矣。涣，离也；节，止也。 ​涣者，阳气陷下，阴气进上，阴阳彼此分离也。节者，险事在外，悦事在内，境遇有困能止也。但阴阳分离，亦有致合之道，是在于陷阳之处，巽缓以渐济之耳。有困能止，即有致通之机，是在于险事之中，和顺以正处之耳。渐以济涣，始离终合，正以立节，有险亦通。然涣者，皆由不知有节之故。若能知节，非礼不履，非道不处，非义不行，境遇在彼，造命在我，何涣之有?故卦德涣之险在内，节之险在外也。解，缓也；蹇，难也。 ​解者，阳气出险而缓也。阳气出险，坎中一阳震动，正阴气退散、阳气难缓之时。阳气难缓，己不为阴气所伤，可以点化群阴矣。蹇者，阳气在险有难也。阳气在险，坎中一阳尚藏，正阴气旺盛、阳气困难之时。阳气困难，非可急求出险，须当静养微阳矣。解之点化群阴者，以其阳气虽出险，阴气犹未消，祸根尚在，即能一时得缓，不久又为阴陷，解而又不解，尤必贵乎出险之动，用增减之功，借阳以退阴。阴气退尽，阳气复全，方是真解蹇。必静养微阳者，以其阳气在于坎，阴气障其阳，若强脱险，不但不能脱险，而且有以致险，不蹇而亦蹇。是必贵乎险中之止，用防闲之道，借阴以保阳，阳气不失，阴气渐退，方能无蹇。阳出险，而当进阳退阴；阳在险，而当养阳防阴。退阴防阴，各有火候，随时而用，方不误事也。睽，外也；家人，内也。 ​睽者，彼此相隔也。火在上而金在下，金火不投，神驰于外，情动于内，因假失真，言其用明于外也。家人者，彼此合一也。木在上而火在下，火中生木，元神守内，柔性应外，以虚求实，言其用明于内也。用明于外，火不返本，妄情动而真情昧；用明于内，火已归根，假化成真，气性消而真性现。明之一内一外，睽与不睽，一家不一家分之。修道者，可不回光返照，以养其明乎!否、泰反其类也。 ​否者，塞室也。刚气用外，柔性藏内，正气散而邪气聚，满腔私欲，塞闭灵窍，柔伤于刚，否之由也。泰者，通达也。刚气在内，柔性在外，严以治己，宽以应物，其心日小，其德日大，刚以柔用，泰之兆也。外刚内柔则否，外柔内刚则泰，总是一刚一柔。所争者，刚柔内外，反其类而否泰分之。刚柔之用，岂可忽焉乎!大壮则止，遁则退也。 ​大壮者，刚之太过也。刚于内而动于外，已刚而又进刚。刚而妄动，动必伤刚，壮之大矣。则止者，可止即止，止以养壮，不使刚进太过也。遁者，刚之收敛也。止其刚而刚于止，已刚而即止刚，刚而止所，不败其刚，遁得其时矣。则退者，可退即退，退以避咎，不使阴气潜生也。盖用刚之道，未刚须进刚，已则须养刚。进刚者用壮也，养刚者藏壮也。当动则动，动而进壮，当止则止，止而藏壮，以时而行，不失其正。动固壮，止亦壮，遁固养，壮亦养，无往而不可刚，无往而有伤刚矣。噫!明进退，知止足，岂愚昧而能为？识急缓，虑吉凶，须匠手以斟酌。大有，众也；同人，亲也。 ​大有者，有之众也。健于内而明于外，实腹之后而能虚心。能虚其心，则元神守室，以火炼金，金遇火而还原生明，大药成就，万理毕集，信步走去，头头是道。以明成健，大有而愈有，其所有者甚众也。同人者，与人亲也。明于内而健于外，虚心之后而又实腹。能实其腹，则正气常存，以金养火，火遇金而返本不燥，阴阳相和，内外合道，寂然不动，感而遂通。以健济明，同人而人同其所同者，最亲也。健而明以火炼金，明而健借金返火。金还火返，金火同宫，金即是火，火即是金，健明如一，有即能同，同而愈有，是谓大有，是谓大同。大有、大同，有阴有阳，有虚有实，有人有我，大小无伤，刚柔两全，浑然天理，一气流行，性命双修之道毕矣。革，去故也；鼎，取新也。 ​革者，去其故而不用也，去故之道。金在上，火在下，以火炼金，去其金之浊气，而返于阳耳。人之妄情为阴金，人之真情为阳金，以元神之真火，煅去妄情之阴金，妄情去而真情现，是谓无情之情，永为不坏之金，所谓“火炼金明”者，是也。鼎者，煅其物而取新也，取新之道。火在上，木在下，火中成木，化其木之浊质，而归于真耳。人之气性为阴木，人之真性为阳木，以元神之真火，煅去气性之阴木，气性化而真性现，是谓无性之性，永为无烟无焰之木，所谓“火中生木”者，是也。革故鼎新，假者去而真者来，金木文并，性情相合，还元返本矣。然必先革故者，先炼己，虚心以待时也。后鼎新者，后采药，实腹以结丹也。可知未虚心而不能实腹，而又当虚心。明之一内一外，性情皆化为真，有为无为，一以贯之也。小过，过也；中孚，信也。 ​小过者，小者过也。止以运动，动必本止，外虚内实，实藏于虚，小者过而大者不过；可止则止，可动则动，动不离止，止于至善无恶之地矣。中孚者，中有信也。悦而渐行，渐以通悦，外实内虚，以虚求实，信于中而行于外；以诚而入，以柔而用，渐进于深造自得之地矣。然不能自小者，亦不能信于中；不能中信者，亦不能小之过。小过、中孚，虚而实，实而虚，虚实并用，动止相需，悦巽如一，过而不过，信在其中，何患修道不成乎!丰，多故也；亲寡，旅也。 ​疑是旅寡亲，今作旅寡亲解。丰者，盛大也。既明且动，动以行明，明动相资，明之足而行之大，丰之极矣。丰极易于自满，自盈不能防闲。明过伤其明，动过败其行，故多故也。多故，则事有反复，行必颠沛矣。旅者，一过而不久留也。即止且明，明本于止，明止相需，止而有养，明而不伤，万事一旅也。旅事即能素位而行，不愿乎外，止于内而不止于外，明于己而不明于人，故寡亲也。寡亲，则物来顺应，事不过留矣。是在保丰者，丰其明而又贵旅明，明不妄动；行旅者，旅其明而又贵丰明，明不太止。丰以旅为用，旅以丰为体，或动而用明，或止而养明，动止皆得其正，可以不伤其明矣。离上，而坎下也。 ​离者，一阴丽于二阳之中，外实内虚，体刚而用柔，其象为火。火性焰上，故离上也。坎者，一阳陷于二阴之中，外虚内实，体柔而用刚，其象为水。水性流下，故坎下也。人之躁性如火，一有触犯，争胜好强，予圣自雄，肆无忌惮，亦火之焰上也。人之欲心如水，妄念百端，弃真入假，逐风扬波，入于下流，亦水之流下也。圣人教人惩忿者，即惩此躁火耳；教人窒欲者，即窒此欲心耳。躁心惩而火返本，则心虚而生明，元神不昧；欲心窒而水归源，则腹实而无险，元精不漏。神明精粹，真水真火，彼此相济，阴阳相合，先天之气，自虚无中来矣。小畜，寡也；履，不处也。 ​小畜者，言其畜之寡也。柔巽畜健，虽刚亦柔，其畜不大，其行不远。履者，言其不下处也。悦于履健，虽柔亦刚，其志能专，其行自力。盖小畜之健在内，真阳未伤，为上德之人。可以有为者，乃以小而畜，浩气不振，甘居卑下，自暴自弃，坐观成败，必至阳极而阴潜生，吉中而凶，暗藏刚为柔钤，有能者归无能矣。履之健在外，真阳已亏，为下德之人。系无能为者，乃能悦于履健，以己求人，从容进步，久于其道，不即不离，必至自近而可达远，自卑而渐登高，柔得刚济，无能者亦有能矣。然则修真之道，不论人之才德高低，只论其有志无志耳。无志，虽才人智士，皆所不能；有志，虽愚夫愚妇，俱能为之。所谓“悟之者立跻圣位，迷之者万劫沉流”也。需，不进也；讼，不亲也。 ​需者，待时也。健在险中，遇险能健，险之在彼，健之在我，欲取于人，不失其己，故需而不进。不进待时，特欲取真阳出坎耳。讼者，争胜也。险在健中，因健有险，内而阴毒，外而凶暴，不但损人，而且伤己，故讼而不亲。不亲好强，终必自陷真阳于坎矣。不进健而健无伤，反借险以养健；不亲人而人不亲，反用健以招险。同一健也，同一险也，健于内有险可以无险，健于外无险亦自致险，一内一外，祸福随之。修道者，可不潜养天德，以防其险乎!大过，颠也；颐，养正也。 ​大过以下卦不反对，先儒以为错简，今暂以反对序。大过者，阳太过也。巽于内而悦于外，阳极而阴即入，阴一入而人心起，见景生情，顺其所欲，性乱命摇，故曰颠也。颐者，取其养也。动于内而止于外，阴极而阳复回，阳一回而道心发，内有主宰，迁善改过，止于其所，故曰养正也。修真之道，始终养正之道也。实腹而能虚心，虚以养实，正而可以不颠；虚心而能实腹，实以济虚，颠而可归于正。故大过之象，内实外虚，示其实必求虚也；颐之象，外实内应，示其虚必求实也。或先实腹而后虚心，或先虚心而后实腹，虚实两用，有为无为之道尽，养正之功毕矣。渐，女归待男行也；归妹，女之终也。 ​渐者，徐缓之义。修道贵乎徐缓，徐缓则止于其所，从容不迫，循序渐进，炼己待时。如卦象少男而配长女，女待男行而后归，此阴阳交合之正，夫妇之真，久则成事，情性如一，阴阳混合也。归妹者，急速之义。修道忌其急速，急速则妄猜私议，不穷实理，任性造作，躐等而求。如卦象少女而求长男，女非其时而苟合，此阴阳交合不正，夫妇之假，久则败事，以女而终，独守孤阴也。修真之道，穷理尽性至命之学也。有火候，有工程，必须用渐修之功，方能深造自得。若急欲成功，冒然下手，其进锐者，其退速，安能追二气于黄道，会三性于元官乎?欲成大道，舍渐修之功，余无他术矣。既济，定也；未济，男之穷也。 ​既济者，阴阳已济也。水上火下，水火烹煎，水得火而不寒，火得水而不燥，水火来往，乾坤为体，坎离为用，良知良能，健顺如一，精神相恋，阴阳混成，故曰定也。定则阴阳俱归黄道，一气流行，生机常存而不息矣。未济者，阴阳相离也。火上水下，火水异处，水下流而火上炎，水不能制火，火不能煎水，良知变为假知，躁性发矣，良能变为假能，欲心生矣。躁性即火，欲心即水，燥性用外，欲心藏内，性乱命摇，阴阳不济，故曰男之穷也。男穷则阳为阴陷，假者用事，真者埋没，而不彰矣。但既济之道，乃阴阳济极之时。济极将不济，须用无为之道以保济。保济之功，用天然真火，煅去后天一切滓质，阴气化而阳气纯，大丹成熟，脱胎神化，入于不生不灭之境矣。未济之道，乃阴阳未济之时。未济须求济，当用有为之功以致济。盖坎中所陷真阳，原是乾宫之物；离中所藏之阴，原是坤宫之物。今者于坎宫欲水之中，取出一点真一之阳水，扑灭离宫之燥火；于离宫燥火之中，取出一点虚灵之真火，煅尽坎宫之欲水。取坎填离，以离归坎，真阴真阳，彼此和合，真水真火，两不相离，未济而至于济，仍是乾健坤顺本面，良知良能原物矣。但保济致济，有为无为，其道不同，下手各别。故既济之义，以明御险也；未济之义，险中出明也。以明御险，防险养明，先天中返后天，所以保济也。险中出明，以明破险，后天中返先天，所以致济也。保济致济之诀，莫过于此。噫!顺则生人生物，逆则为圣为贤。逆之一字，岂易知乎!姤，遇也，柔遇刚也；夬，决也，刚决柔也。 ​姤者，遇也。以一柔而遇五刚，阳极而阴潜生，不期遇而忽遇，阴气乘间而入也。夬者，决也。以五刚而决一柔，阳将纯而阴将尽，不强决而自决，阳气随时而进也。人自有生以后，一点先天阳气，藏于幻身之中，日生夜长，年至二八，先天气足，名曰纯阳之体，为上德之人。当此之时，若遇明师指点，行无为自然之道，以成后天之功，性了而命亦全，便为无漏真人矣。否则，阳极必阴，一阴潜生于纯阳之下，阴姤其阳，后天用事，阴日长，阳日消，不至消灭其阳而不止。一阴虽微，为祸最烈。金丹有为之道，正为中下之人姤后而设。有为者，进阳决阴也。以阳决阴，必先于阴中进阳，进阳正为退阴计耳。阳气进于九五中正之位，是正位凝命，阳气已足，阴气已弱，纵横逆顺，道心用事，金丹有象，于此点化群阴，如猫捕鼠。但一切群阴皆化，仅有一点阴气之根未消，犹足为道累。圣胎虽结，不能脱化。古真云“一毫阴气不尽不仙”，正言此群阴之根也。群阴之根为何根?即人心识神是也。识神者，历劫轮回之种子，生生死死之根蒂，其权最大，其根最深，在姤为初生之一阴，在夬为决终之一阴。姤时他先发，夬时他后去，生人者是他，死人者是他，人多贪恋，不肯果决除去，即欲去之，亦不易于去。去之之道，健而能和，刚以柔用，不即不离，勿忘勿助，待其党类已尽，势孤力单，一决即去，拔去历劫祸根，现出父母未生以前本相，圆陀陀、光灼灼、净倮倮、赤洒洒，不生不灭，为金刚不坏之物矣。君子道长，小人道忧也。 ​易之道，一阳一阴之道也。阴为柔，阳为刚。刚之德主健，柔之德主顺。健则易知，顺则简能。易知即人之良知，简能即人之良能。良知本于天，属命；良能本于地，属性。人秉天地易简之德，知能俱良，刚柔兼该，性命寓于一身矣。及交后天，良知变为假知，良能变为假能，阴阳不调，刚柔不当，性乱命摇，失其秉受天地简易知能之良。孟子所谓“人之所以异于禽兽者几希，庶民去之，君子存之”。存此良知良能，则为君子；失此良知良能，则为庶人。君子道长，君子存之也。小人道忧，庶民去之也。盖君子之道，复此良知良能，而退假知假能，故长；小人之道，顺其假知假能，而弃良知良能，故忧。良知良能属于先天，假知假能属于后天。复其先天之真，则了性了命，入于生路，道之长也；顺其后天之假，则昧性伤命，入于死路，道之忧也。六十四卦，以乾坤为门户者，示人以刚柔简易之道也；其余六十二卦者，示人以变化简易之道也。六十四卦，三百八十四爻，无非教人知其不简易，而变之化之，期归于简易耳。变化简易，知能俱良，而为君子；不变化简易，则知能不良，而为小人。君子小人，只在知变化不知变化上分别耳。金丹之道，君子之道。君子之道，即逆运阴阳之道也。所谓金丹者，即简易良知良能混成之性。所谓还丹者，即还此简易良知良能之本面。所谓金液大丹者，即煅炼此简易良知良能混成之性，永久不坏也。所谓火候者，即六十四卦变化简易知能，俱归于良之道也。所谓药物者，即刚柔简易知能俱良之德也。所谓圣胎者，即刚柔简易知能俱归于良也。所谓脱胎者，即刚柔混成、简易不拘、知能入神、有无不立也。丹经子书千帙万卷，总不外易理。易理六十四卦，三百八十四爻，总不出此刚柔简易知能俱良之道。易为君子谋，不为小人谋，特以君子能修此刚柔简易之道，逆运阴阳，复还本来良知良能之原物也。一切凡夫小人，认假为真，顺其后天阴阳，适以昧其天根，自取灭亡已耳，焉知修此先天道运大道乎!",-1)])])}const f=t(c,[["render",o]]);export{_ as __pageData,f as default};
